UPDATE public.facts f
SET
  hook = hook_updates.hook,
  source_url = COALESCE(hook_updates.source_url, f.source_url),
  content = COALESCE(hook_updates.new_content, f.content),
  updated_at = now()
FROM hook_updates
WHERE f.slug = hook_updates.slug;

-- 3) Insertion de 100 nouveaux faits
WITH new_facts(slug, title, hook, content, source, source_url, category_slug, display_order, accent_color, tone) AS (
  VALUES
  ('la-prise-de-la-bastille-na-pas-libere-beaucoup-de-prisonniers', 'La prise de la Bastille n’a pas libéré beaucoup de prisonniers.', 'Le symbole est plus grand que l’événement lui-même.', 'Le 14 juillet 1789, la Bastille ne contenait que quelques prisonniers. Mais sa chute frappe les esprits parce qu’elle représente l’effondrement d’un symbole du pouvoir royal.', 'Encyclopaedia Britannica', 'https://www.britannica.com/event/French-Revolution', 'histoire-essentielle', 101, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('le-debarquement-de-normandie-a-eu-lieu-le-6-juin-1944', 'Le débarquement de Normandie a eu lieu le 6 juin 1944.', 'Le D-Day ouvre la libération de l’Europe de l’Ouest.', 'Des milliers de soldats alliés débarquent sur les plages normandes pour ouvrir un nouveau front contre l’Allemagne nazie. Cette opération devient l’un des tournants majeurs de la Seconde Guerre mondiale.', 'Imperial War Museums', 'https://www.iwm.org.uk/history/the-10-things-you-need-to-know-about-d-day', 'histoire-essentielle', 102, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('la-seconde-guerre-mondiale-se-termine-en-1945', 'La Seconde Guerre mondiale se termine en 1945.', '1945 marque la fin du conflit le plus meurtrier du XXe siècle.', 'La capitulation de l’Allemagne puis celle du Japon mettent fin à six années de guerre mondiale. Cette date reste un repère essentiel pour comprendre l’Europe, l’ONU et le monde contemporain.', 'Encyclopaedia Britannica', 'https://www.britannica.com/event/World-War-II', 'histoire-essentielle', 103, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('la-renaissance-redecouvre-les-savoirs-de-lantiquite', 'La Renaissance redécouvre les savoirs de l’Antiquité.', 'La Renaissance remet l’humain et la curiosité au centre.', 'À partir de l’Italie, artistes et savants s’inspirent des textes grecs et romains pour repenser l’art, la science et la place de l’humain. C’est pour cela qu’on associe cette période à un grand réveil culturel.', 'Encyclopaedia Britannica', 'https://www.britannica.com/event/Renaissance', 'histoire-essentielle', 104, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('la-chute-de-constantinople-date-de-1453', 'La chute de Constantinople date de 1453.', '1453 marque la fin d’un empire vieux de plus de mille ans.', 'Quand les Ottomans prennent Constantinople, l’Empire byzantin disparaît. Cette date est souvent utilisée comme repère pour comprendre la transition entre Moyen Âge et époque moderne.', 'Encyclopaedia Britannica', 'https://www.britannica.com/event/Fall-of-Constantinople-1453', 'histoire-essentielle', 105, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('le-canal-de-suez-raccourcit-le-trajet-entre-leurope-et-lasie', 'Le canal de Suez raccourcit le trajet entre l’Europe et l’Asie.', 'Un canal change les routes du commerce mondial.', 'Ouvert en 1869, il évite aux navires de contourner toute l’Afrique pour passer de la Méditerranée à la mer Rouge. C’est une œuvre technique, mais aussi un enjeu stratégique majeur.', 'Suez Canal Authority', 'https://www.suezcanal.gov.eg/English/About/SuezCanal/Pages/CanalHistory.aspx', 'histoire-essentielle', 106, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('le-code-civil-de-napoleon-influence-encore-le-droit', 'Le code civil de Napoléon influence encore le droit.', 'Un texte de 1804 structure encore la vie quotidienne.', 'Le Code civil organise des règles sur la famille, la propriété ou les contrats. Il a été exporté ou imité dans plusieurs pays, ce qui explique pourquoi Napoléon n’est pas seulement une figure militaire.', 'Vie publique', 'https://www.vie-publique.fr/fiches/19567-quest-ce-que-le-code-civil', 'histoire-essentielle', 107, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('la-guerre-de-cent-ans-na-pas-dure-exactement-cent-ans', 'La guerre de Cent Ans n’a pas duré exactement cent ans.', 'Le nom est plus simple que la réalité historique.', 'Ce conflit entre royaumes de France et d’Angleterre s’étend de 1337 à 1453, avec des périodes de trêve. Son nom donne une image simple d’une rivalité beaucoup plus longue et complexe.', 'Encyclopaedia Britannica', 'https://www.britannica.com/event/Hundred-Years-War', 'histoire-essentielle', 108, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('jeanne-darc-devient-celebre-pendant-la-guerre-de-cent-ans', 'Jeanne d’Arc devient célèbre pendant la guerre de Cent Ans.', 'Une adolescente devient un symbole national français.', 'Elle affirme avoir une mission divine et participe à la reprise d’Orléans en 1429. Son histoire mêle guerre, religion et construction d’un grand récit national.', 'Encyclopaedia Britannica', 'https://www.britannica.com/biography/Saint-Joan-of-Arc', 'histoire-essentielle', 109, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('la-guerre-du-vietnam-a-profondement-divise-les-etats-unis', 'La guerre du Vietnam a profondément divisé les États-Unis.', 'Une guerre lointaine devient une crise intérieure américaine.', 'Au-delà du conflit en Asie, la guerre provoque d’immenses manifestations et une remise en question de l’autorité politique aux États-Unis. Elle reste un repère majeur des années 1960 et 1970.', 'National Archives', 'https://www.archives.gov/research/vietnam-war', 'histoire-essentielle', 110, '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('citizen-kane-est-souvent-cite-comme-lun-des-plus-grands-films-de-lhistoire', 'Citizen Kane est souvent cité comme l’un des plus grands films de l’histoire.', 'Un film de 1941 a changé la manière de raconter au cinéma.', 'Orson Welles y utilise des angles, des lumières et une construction narrative très modernes pour l’époque. Même sans l’avoir vu, connaître son importance aide à mieux situer l’histoire du cinéma.', 'British Film Institute', 'https://www.bfi.org.uk/film/edfd6695-bc20-5147-b163-e7d7675a6b5f/citizen-kane', 'cinema-culture-pop', 111, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('le-seigneur-des-anneaux-a-transforme-la-fantasy-au-cinema', 'Le Seigneur des anneaux a transformé la fantasy au cinéma.', 'La fantasy devient un spectacle mondial grand public.', 'Avant la trilogie de Peter Jackson, beaucoup doutaient qu’un univers aussi vaste puisse fonctionner au cinéma. Son succès a montré qu’un monde imaginaire pouvait devenir un phénomène culturel massif.', 'Academy of Motion Picture Arts and Sciences', 'https://www.oscars.org/oscars/ceremonies/2004', 'cinema-culture-pop', 112, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('matrix-a-rendu-celebre-lidee-de-pilule-rouge', 'Matrix a rendu célèbre l’idée de “pilule rouge”.', 'Une scène de science-fiction devient une métaphore culturelle.', 'Dans le film, choisir la pilule rouge signifie accepter une vérité inconfortable plutôt que rester dans l’illusion. L’image est devenue une référence bien au-delà du cinéma.', 'Warner Bros.', 'https://www.warnerbros.com/movies/matrix', 'cinema-culture-pop', 113, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('toy-story-est-le-premier-long-metrage-entierement-en-images-de-synthese', 'Toy Story est le premier long-métrage entièrement en images de synthèse.', 'Un film de jouets ouvre une nouvelle époque de l’animation.', 'Sorti en 1995, Toy Story prouve qu’un film animé par ordinateur peut toucher le grand public. Après lui, l’animation numérique devient progressivement dominante.', 'Pixar', 'https://www.pixar.com/feature-films/toy-story', 'cinema-culture-pop', 114, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('le-cinema-muet-netait-pas-vraiment-silencieux', 'Le cinéma muet n’était pas vraiment silencieux.', 'Les films muets avaient souvent une musique en salle.', 'Dans les salles, un pianiste, un orchestre ou des effets sonores accompagnaient souvent la projection. Le public ne regardait donc pas les films dans un silence total.', 'Library of Congress', 'https://www.loc.gov/collections/silent-film-sheet-music/about-this-collection/', 'cinema-culture-pop', 115, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('avatar-a-popularise-la-3d-moderne-au-cinema', 'Avatar a popularisé la 3D moderne au cinéma.', 'Un succès mondial relance l’envie de voir des films en 3D.', 'Le film de James Cameron a marqué par son univers visuel et son usage spectaculaire de la 3D. Après sa sortie, beaucoup de blockbusters ont cherché à reproduire cet effet d’immersion.', 'Academy of Motion Picture Arts and Sciences', 'https://www.oscars.org/oscars/ceremonies/2010', 'cinema-culture-pop', 116, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('le-festival-de-cannes-a-ete-cree-apres-un-contexte-politique-tendu', 'Le Festival de Cannes a été créé après un contexte politique tendu.', 'Cannes naît aussi pour défendre une certaine liberté du cinéma.', 'L’idée apparaît à la fin des années 1930, face aux pressions politiques qui pesaient sur d’autres festivals européens. Cannes devient ensuite l’un des plus grands rendez-vous du cinéma mondial.', 'Festival de Cannes', 'https://www.festival-cannes.com/en/the-festival/history/', 'cinema-culture-pop', 117, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('les-oscars-existent-depuis-1929', 'Les Oscars existent depuis 1929.', 'Une cérémonie professionnelle devient un événement mondial.', 'Au départ, la première cérémonie est beaucoup plus courte et discrète qu’aujourd’hui. Avec le temps, les Oscars deviennent l’un des grands symboles de la reconnaissance à Hollywood.', 'Academy of Motion Picture Arts and Sciences', 'https://www.oscars.org/oscars/ceremonies/1929', 'cinema-culture-pop', 118, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('le-cinema-danimation-japonais-doit-beaucoup-au-studio-ghibli', 'Le cinéma d’animation japonais doit beaucoup au Studio Ghibli.', 'Ghibli rend l’animation japonaise visible dans le monde entier.', 'Avec des films comme Mon voisin Totoro ou Le Voyage de Chihiro, le studio impose un style poétique et reconnaissable. Il devient une porte d’entrée majeure vers la culture japonaise contemporaine.', 'Studio Ghibli', 'https://www.ghibli.jp/', 'cinema-culture-pop', 119, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('les-blockbusters-modernes-doivent-beaucoup-a-star-wars-et-aux-dents-de-la-mer', 'Les blockbusters modernes doivent beaucoup à Star Wars et aux Dents de la mer.', 'Hollywood apprend à transformer un film en événement.', 'Ces succès montrent qu’une sortie massive, du marketing et des produits dérivés peuvent faire d’un film un phénomène culturel. Cette logique influence encore le cinéma populaire actuel.', 'Smithsonian Magazine', 'https://www.smithsonianmag.com/innovation/how-star-wars-revolutionized-entertainment-180961376/', 'cinema-culture-pop', 120, '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('aristote-a-influence-la-pensee-occidentale-pendant-des-siecles', 'Aristote a influencé la pensée occidentale pendant des siècles.', 'Aristote est l’un des grands noms derrière notre manière de classer le monde.', 'Il a écrit sur la logique, la politique, la nature, l’éthique et l’art. Même sans lire ses textes, on retrouve son influence dans une grande partie de la culture européenne.', 'Encyclopaedia Britannica', 'https://www.britannica.com/biography/Aristotle', 'grandes-figures', 121, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('socrate-na-laisse-aucun-livre', 'Socrate n’a laissé aucun livre.', 'On connaît Socrate surtout grâce à ceux qui ont parlé de lui.', 'Il a marqué la philosophie en questionnant les évidences plutôt qu’en donnant des leçons. Son élève Platon a ensuite raconté une grande partie de sa pensée.', 'Encyclopaedia Britannica', 'https://www.britannica.com/biography/Socrates', 'grandes-figures', 122, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('platon-a-fonde-une-ecole-appelee-lacademie', 'Platon a fondé une école appelée l’Académie.', 'Le mot académie vient d’un lieu de philosophie antique.', 'À Athènes, Platon fonde une école où l’on réfléchit aux idées, à la politique et au savoir. Son influence est si forte que le mot “académie” reste associé à la connaissance.', 'Encyclopaedia Britannica', 'https://www.britannica.com/biography/Plato', 'grandes-figures', 123, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('charles-darwin-a-change-notre-maniere-de-voir-le-vivant', 'Charles Darwin a changé notre manière de voir le vivant.', 'Darwin rend l’évolution impossible à ignorer.', 'Avec sa théorie de la sélection naturelle, il propose une explication simple et puissante : les espèces changent au fil du temps parce que certains traits aident à survivre et se transmettre.', 'Natural History Museum', 'https://www.nhm.ac.uk/discover/charles-darwin-most-famous-biologist.html', 'grandes-figures', 124, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('ada-lovelace-est-souvent-presentee-comme-la-premiere-programmeuse', 'Ada Lovelace est souvent présentée comme la première programmeuse.', 'Une femme imagine déjà ce que pourrait faire une machine.', 'Au XIXe siècle, elle comprend que la machine de Charles Babbage pourrait manipuler autre chose que des nombres. Son intuition la relie aux débuts de l’informatique.', 'Computer History Museum', 'https://www.computerhistory.org/babbage/adalovelace/', 'grandes-figures', 125, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('simone-de-beauvoir-a-marque-lhistoire-du-feminisme', 'Simone de Beauvoir a marqué l’histoire du féminisme.', 'Une phrase résume une révolution de pensée.', 'Dans Le Deuxième Sexe, elle écrit qu’“on ne naît pas femme, on le devient”. L’idée est devenue centrale pour comprendre la place de l’éducation et de la société dans les rôles de genre.', 'Encyclopaedia Britannica', 'https://www.britannica.com/biography/Simone-de-Beauvoir', 'grandes-figures', 126, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('winston-churchill-devient-un-symbole-de-resistance-pendant-la-seconde-guerre-mondiale', 'Winston Churchill devient un symbole de résistance pendant la Seconde Guerre mondiale.', 'Ses discours donnent une voix à la résistance britannique.', 'Premier ministre britannique en 1940, il incarne la détermination face à l’Allemagne nazie. Ses phrases fortes ont marqué l’imaginaire de la guerre.', 'Imperial War Museums', 'https://www.iwm.org.uk/history/how-churchill-led-britain-to-victory-in-the-second-world-war', 'grandes-figures', 127, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('frida-kahlo-a-transforme-sa-douleur-en-peinture', 'Frida Kahlo a transformé sa douleur en peinture.', 'Son visage devient une œuvre autant qu’un symbole.', 'Après un grave accident, elle peint souvent son propre corps, ses souffrances et son identité. Ses autoportraits sont devenus des images fortes de l’art du XXe siècle.', 'Frida Kahlo Museum', 'https://www.museofridakahlo.org.mx/en/frida-kahlo/', 'grandes-figures', 128, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('malala-yousafzai-devient-celebre-pour-son-combat-pour-leducation', 'Malala Yousafzai devient célèbre pour son combat pour l’éducation.', 'Une adolescente devient un symbole mondial de l’école pour les filles.', 'Après avoir été attaquée pour avoir défendu le droit des filles à apprendre, elle continue son engagement. Elle reçoit ensuite le prix Nobel de la paix très jeune.', 'Nobel Prize', 'https://www.nobelprize.org/prizes/peace/2014/yousafzai/facts/', 'grandes-figures', 129, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('stephen-hawking-a-rendu-la-cosmologie-visible-au-grand-public', 'Stephen Hawking a rendu la cosmologie visible au grand public.', 'Il transforme des questions vertigineuses en culture populaire.', 'Ses travaux portent sur les trous noirs et l’univers, mais son livre Une brève histoire du temps l’a fait connaître bien au-delà des scientifiques.', 'University of Cambridge', 'https://www.cam.ac.uk/stephenhawking', 'grandes-figures', 130, '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('les-miserables-nest-pas-seulement-lhistoire-de-jean-valjean', 'Les Misérables n’est pas seulement l’histoire de Jean Valjean.', 'Victor Hugo raconte aussi la misère sociale de son époque.', 'Le roman parle de justice, de pauvreté, de rédemption et de violence sociale. C’est pour cela qu’il reste une grande référence culturelle, bien au-delà de son intrigue.', 'Maison de Victor Hugo', 'https://www.maisonsvictorhugo.paris.fr/', 'art-litterature', 131, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('1984-a-donne-un-vocabulaire-a-la-surveillance-moderne', '1984 a donné un vocabulaire à la surveillance moderne.', 'Orwell aide à nommer la peur d’un pouvoir qui surveille tout.', 'Le roman imagine une société où l’État contrôle la vérité, le langage et les comportements. Des expressions comme “Big Brother” sont devenues des références politiques courantes.', 'British Library', 'https://www.bl.uk/20th-century-literature/articles/an-introduction-to-nineteen-eighty-four', 'art-litterature', 132, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('don-quichotte-est-souvent-considere-comme-lun-des-premiers-grands-romans-modernes', 'Don Quichotte est souvent considéré comme l’un des premiers grands romans modernes.', 'Un chevalier imaginaire ouvre la voie au roman moderne.', 'Cervantès y raconte un homme qui confond ses lectures avec la réalité. Le livre est drôle, triste et très moderne dans sa manière de jouer avec les illusions.', 'Encyclopaedia Britannica', 'https://www.britannica.com/topic/Don-Quixote-novel', 'art-litterature', 133, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('le-cri-de-munch-nest-pas-seulement-une-image-dangoisse', 'Le Cri de Munch n’est pas seulement une image d’angoisse.', 'Une peinture devient le visage universel de l’anxiété.', 'Avec son personnage qui semble hurler devant un ciel déformé, le tableau donne une forme simple à une émotion très difficile à décrire.', 'Munchmuseet', 'https://www.munchmuseet.no/en/edvard-munch/the-scream/', 'art-litterature', 134, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('le-plafond-de-la-chapelle-sixtine-a-ete-peint-par-michel-ange', 'Le plafond de la chapelle Sixtine a été peint par Michel-Ange.', 'Une commande religieuse devient un monument de l’art mondial.', 'Michel-Ange passe des années à peindre des scènes bibliques au plafond de la chapelle. L’image de la Création d’Adam est devenue l’une des plus reconnaissables de l’histoire de l’art.', 'Vatican Museums', 'https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina.html', 'art-litterature', 135, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('moliere-a-donne-son-nom-a-la-langue-francaise', 'Molière a donné son nom à la langue française.', 'Dire “la langue de Molière”, c’est parler du français.', 'Ses pièces ont marqué le théâtre par leur humour et leur critique des comportements sociaux. Son nom est devenu un raccourci culturel pour désigner la littérature française.', 'Comédie-Française', 'https://www.comedie-francaise.fr/fr/moliere', 'art-litterature', 136, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('notre-dame-de-paris-a-aide-a-sauver-la-cathedrale', 'Notre-Dame de Paris a aidé à sauver la cathédrale.', 'Un roman peut changer le regard sur un monument.', 'Le livre de Victor Hugo a ravivé l’intérêt pour la cathédrale, alors abîmée et moins valorisée. La fiction a donc joué un rôle dans la redécouverte d’un patrimoine réel.', 'Bibliothèque nationale de France', 'https://gallica.bnf.fr/essentiels/hugo/notre-dame-paris', 'art-litterature', 137, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('la-venus-de-milo-est-celebre-malgre-ses-bras-manquants', 'La Vénus de Milo est célèbre malgré ses bras manquants.', 'L’absence fait partie de son mystère.', 'Découverte au XIXe siècle, la statue devient l’un des symboles du Louvre. Ses bras disparus ont nourri l’imaginaire autour de sa posture et de son histoire.', 'Musée du Louvre', 'https://www.louvre.fr/decouvrir/le-palais/la-venus-de-milo', 'art-litterature', 138, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('le-street-art-est-passe-de-la-rue-aux-musees', 'Le street art est passé de la rue aux musées.', 'Un art longtemps illégal devient reconnu culturellement.', 'Ce qui était souvent vu comme une dégradation urbaine est devenu, pour certains artistes, une forme d’expression exposée et vendue. Banksy illustre bien ce basculement.', 'Tate', 'https://www.tate.org.uk/art/art-terms/s/street-art', 'art-litterature', 139, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('la-divine-comedie-a-faconne-notre-image-de-lenfer', 'La Divine Comédie a façonné notre image de l’enfer.', 'Dante donne une architecture à l’imaginaire de l’au-delà.', 'Son œuvre décrit un voyage à travers l’Enfer, le Purgatoire et le Paradis. Beaucoup d’images modernes de l’enfer doivent quelque chose à cette vision médiévale.', 'Encyclopaedia Britannica', 'https://www.britannica.com/topic/The-Divine-Comedy', 'art-litterature', 140, '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('le-placebo-peut-produire-de-vrais-effets', 'Le placebo peut produire de vrais effets.', 'Croire à un traitement peut déjà influencer le corps.', 'Quand une personne pense recevoir un soin efficace, son cerveau peut déclencher des réactions mesurables. Cela ne remplace pas un traitement, mais montre le lien puissant entre attente et perception.', 'Harvard Health Publishing', 'https://www.health.harvard.edu/mental-health/the-power-of-the-placebo-effect', 'science-cerveau', 141, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('ton-cerveau-voit-parfois-ce-quil-sattend-a-voir', 'Ton cerveau voit parfois ce qu’il s’attend à voir.', 'La perception n’est pas une simple caméra.', 'Le cerveau utilise le contexte et les souvenirs pour interpréter le monde. C’est pour cela que les illusions fonctionnent : on ne voit pas seulement avec les yeux, mais aussi avec l’interprétation.', 'American Psychological Association', 'https://www.apa.org/topics/sensation-perception', 'science-cerveau', 142, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('les-reves-sont-souvent-oublies-tres-vite', 'Les rêves sont souvent oubliés très vite.', 'Le réveil efface souvent les rêves avant qu’on les attrape.', 'Au moment où l’on se réveille, le cerveau ne fixe pas toujours le rêve en mémoire longue. C’est pour cela qu’un rêve peut sembler très clair puis disparaître en quelques secondes.', 'Sleep Foundation', 'https://www.sleepfoundation.org/dreams', 'science-cerveau', 143, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('le-gout-depend-beaucoup-de-lodorat', 'Le goût dépend beaucoup de l’odorat.', 'Manger, c’est aussi sentir.', 'Quand le nez est bouché, les aliments paraissent souvent fades. Une grande partie de ce qu’on appelle “goût” vient en réalité des odeurs qui remontent vers le nez.', 'Monell Chemical Senses Center', 'https://monell.org/smell-taste/', 'science-cerveau', 144, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('les-bebes-reconnaissent-des-voix-avant-de-comprendre-les-mots', 'Les bébés reconnaissent des voix avant de comprendre les mots.', 'La voix crée un lien avant le langage.', 'Même très tôt, un bébé peut réagir à des voix familières. Avant de comprendre le sens précis des phrases, il perçoit déjà le rythme, le ton et la présence.', 'American Academy of Pediatrics', 'https://www.healthychildren.org/English/ages-stages/baby/Pages/Language-Development-4-to-7-Months.aspx', 'science-cerveau', 145, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('les-chats-ronronnent-aussi-quand-ils-ne-sont-pas-detendus', 'Les chats ronronnent aussi quand ils ne sont pas détendus.', 'Le ronronnement n’est pas seulement un signe de bonheur.', 'Un chat peut ronronner lorsqu’il est apaisé, mais aussi quand il est stressé, blessé ou cherche du réconfort. Le même son peut donc avoir plusieurs fonctions.', 'Cornell Feline Health Center', 'https://www.vet.cornell.edu/departments-centers-and-institutes/cornell-feline-health-center', 'science-cerveau', 146, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('les-chiens-comprennent-surtout-nos-gestes-et-notre-ton', 'Les chiens comprennent surtout nos gestes et notre ton.', 'Le langage humain passe aussi par le corps.', 'Un chien peut réagir à certains mots, mais il lit aussi énormément la posture, les habitudes et l’intonation. C’est pourquoi il semble parfois comprendre plus qu’une simple phrase.', 'American Kennel Club', 'https://www.akc.org/expert-advice/lifestyle/dogs-understand-words/', 'science-cerveau', 147, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('la-cafeine-bloque-surtout-le-signal-de-fatigue', 'La caféine bloque surtout le signal de fatigue.', 'Le café ne donne pas de l’énergie, il masque une partie de la fatigue.', 'La caféine agit sur les récepteurs liés à l’adénosine, une molécule qui favorise la sensation de fatigue. Résultat : on se sent plus alerte, même si le besoin de repos existe toujours.', 'Harvard T.H. Chan School of Public Health', 'https://www.hsph.harvard.edu/nutritionsource/food-features/coffee/', 'science-cerveau', 148, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('les-empreintes-digitales-se-forment-avant-la-naissance', 'Les empreintes digitales se forment avant la naissance.', 'Chaque main porte une histoire commencée dans le ventre.', 'Elles apparaissent pendant le développement du fœtus et dépendent de facteurs génétiques et physiques. C’est ce qui les rend si particulières d’une personne à l’autre.', 'National Institute of Justice', 'https://nij.ojp.gov/topics/articles/fingerprint-sourcebook', 'science-cerveau', 149, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('le-baillement-est-etonnamment-contagieux', 'Le bâillement est étonnamment contagieux.', 'Voir quelqu’un bâiller peut suffire à déclencher le tien.', 'Ce phénomène semble lié à l’attention sociale et à l’empathie, même si tout n’est pas encore parfaitement compris. C’est un petit comportement qui rappelle à quel point nous sommes influencés par les autres.', 'Scientific American', 'https://www.scientificamerican.com/article/why-are-yawns-contagious/', 'science-cerveau', 150, '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('le-qr-code-a-ete-invente-pour-suivre-des-pieces-automobiles', 'Le QR code a été inventé pour suivre des pièces automobiles.', 'Un outil d’usine est devenu un geste du quotidien.', 'Créé au Japon dans les années 1990, le QR code servait d’abord à identifier rapidement des composants. Il est ensuite devenu courant pour ouvrir des menus, des billets ou des paiements.', 'DENSO Wave', 'https://www.qrcode.com/en/history/', 'inventions-technologie', 151, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('bluetooth-porte-le-nom-dun-roi-viking', 'Bluetooth porte le nom d’un roi viking.', 'Une technologie sans fil cache une référence médiévale.', 'Le nom vient de Harald “Bluetooth”, un roi connu pour avoir uni des territoires. L’idée plaisait aux créateurs de la technologie, qui voulaient unir différents appareils.', 'Bluetooth SIG', 'https://www.bluetooth.com/about-us/bluetooth-origin/', 'inventions-technologie', 152, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('la-souris-dordinateur-a-ete-presentee-des-les-annees-1960', 'La souris d’ordinateur a été présentée dès les années 1960.', 'Avant d’être évidente, la souris était une idée futuriste.', 'Douglas Engelbart la montre lors d’une démonstration célèbre en 1968. À l’époque, manipuler un ordinateur avec un petit objet sur une table paraît très nouveau.', 'Computer History Museum', 'https://computerhistory.org/blog/the-mother-of-all-demos/', 'inventions-technologie', 153, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('le-wi-fi-ne-signifie-pas-vraiment-wireless-fidelity', 'Le Wi-Fi ne signifie pas vraiment “Wireless Fidelity”.', 'Un nom très technique est surtout une marque facile à retenir.', 'L’expression a été choisie pour rendre une technologie complexe plus mémorable. Aujourd’hui, le mot Wi-Fi est devenu plus connu que les normes techniques qu’il désigne.', 'Wi-Fi Alliance', 'https://www.wi-fi.org/who-we-are/history', 'inventions-technologie', 154, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('le-sms-etait-limite-a-160-caracteres', 'Le SMS était limité à 160 caractères.', 'Une contrainte technique a façonné notre manière d’écrire.', 'Cette limite a poussé les utilisateurs à raccourcir les mots et à aller droit au but. Une contrainte invisible a donc influencé le langage mobile pendant des années.', 'GSM Association', 'https://www.gsma.com/aboutus/history', 'inventions-technologie', 155, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('la-premiere-console-playstation-est-nee-apres-un-desaccord-avec-nintendo', 'La première console PlayStation est née après un désaccord avec Nintendo.', 'Un projet abandonné donne naissance à une console mythique.', 'Sony travaillait d’abord avec Nintendo sur un lecteur CD. Après l’échec de l’accord, Sony lance sa propre console, qui deviendra l’une des grandes marques du jeu vidéo.', 'Sony Interactive Entertainment', 'https://www.playstation.com/en-us/corporate/about-us/', 'inventions-technologie', 156, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('la-pile-electrique-moderne-commence-avec-volta', 'La pile électrique moderne commence avec Volta.', 'Une invention donne son nom au “volt”.', 'Au début du XIXe siècle, Alessandro Volta crée un dispositif capable de produire un courant électrique continu. Son nom est resté dans l’unité de tension électrique.', 'Encyclopaedia Britannica', 'https://www.britannica.com/biography/Alessandro-Volta', 'inventions-technologie', 157, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('le-telescope-a-change-la-place-de-lhumain-dans-lunivers', 'Le télescope a changé la place de l’humain dans l’univers.', 'Regarder plus loin a forcé à penser autrement.', 'Avec les observations de Galilée, les astres ne sont plus seulement des points lumineux. Le ciel devient un objet d’étude, et certaines certitudes anciennes commencent à vaciller.', 'NASA', 'https://science.nasa.gov/mission/hubble/overview/history-of-the-telescope/', 'inventions-technologie', 158, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('la-boussole-a-rendu-les-grands-voyages-plus-surs', 'La boussole a rendu les grands voyages plus sûrs.', 'Un petit instrument a ouvert de grandes routes.', 'En indiquant une direction même quand les repères visuels manquent, elle a facilité la navigation en mer. C’est l’un des outils qui ont rendu possibles de longues explorations.', 'Encyclopaedia Britannica', 'https://www.britannica.com/technology/compass-navigational-instrument', 'inventions-technologie', 159, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('la-radio-a-permis-dentendre-le-monde-en-direct', 'La radio a permis d’entendre le monde en direct.', 'Avant Internet, la radio crée déjà une présence à distance.', 'Elle permet de transmettre des voix, des nouvelles et de la musique à de grandes distances. Pour beaucoup de foyers, elle a été le premier média du direct.', 'Library of Congress', 'https://www.loc.gov/collections/radio-broadcasts/about-this-collection/', 'inventions-technologie', 160, '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('le-week-end-est-une-invention-sociale-relativement-recente', 'Le week-end est une invention sociale relativement récente.', 'Avoir deux jours de repos n’a rien de naturel.', 'Pendant longtemps, le rythme du travail laissait beaucoup moins de place aux loisirs. Le week-end moderne s’est construit avec les luttes sociales, l’industrie et l’évolution des modes de vie.', 'Encyclopaedia Britannica', 'https://www.britannica.com/topic/week', 'quotidien-societe', 161, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('les-soldes-servent-aussi-a-vider-les-stocks', 'Les soldes servent aussi à vider les stocks.', 'Une réduction est souvent un outil de gestion.', 'Pour les magasins, baisser les prix permet d’écouler des produits avant une nouvelle saison. Ce n’est donc pas seulement un cadeau au client, mais aussi une stratégie commerciale.', 'Service public', 'https://www.service-public.fr/particuliers/vosdroits/F1015', 'quotidien-societe', 162, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('les-files-dattente-ont-leurs-propres-regles-sociales', 'Les files d’attente ont leurs propres règles sociales.', 'Attendre paraît simple, mais c’est très codifié.', 'Respecter l’ordre, garder une distance ou s’agacer contre ceux qui doublent montre que la file repose sur une idée de justice partagée. Un geste banal révèle une règle sociale forte.', 'BBC', 'https://www.bbc.com/future/article/20150512-why-queues-are-fair', 'quotidien-societe', 163, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('le-pourboire-na-pas-le-meme-sens-partout', 'Le pourboire n’a pas le même sens partout.', 'Un geste poli peut devenir une règle économique.', 'Dans certains pays, il reste facultatif. Dans d’autres, il complète fortement le salaire des serveurs. La même action peut donc être perçue très différemment selon la culture.', 'Smithsonian Magazine', 'https://www.smithsonianmag.com/history/the-restaurant-tip-180959057/', 'quotidien-societe', 164, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('le-costume-cravate-vient-dun-long-heritage-europeen', 'Le costume-cravate vient d’un long héritage européen.', 'Une tenue professionnelle cache une histoire de statut social.', 'La veste, la chemise et la cravate se sont imposées progressivement comme signes de sérieux et de respectabilité. Ce qui paraît neutre aujourd’hui est aussi un code social.', 'Victoria and Albert Museum', 'https://www.vam.ac.uk/articles/a-history-of-mens-fashion', 'quotidien-societe', 165, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('les-logos-sont-penses-pour-etre-reconnus-tres-vite', 'Les logos sont pensés pour être reconnus très vite.', 'Une bonne marque doit se lire presque d’un coup d’œil.', 'Formes simples, couleurs fortes et répétition aident le cerveau à reconnaître une marque sans effort. C’est pourquoi certains logos deviennent des symboles culturels.', 'Design Museum', 'https://designmuseum.org/', 'quotidien-societe', 166, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('les-feux-rouges-reprennent-un-code-venu-du-rail', 'Les feux rouges reprennent un code venu du rail.', 'La route a hérité de signaux pensés pour les trains.', 'Avant les voitures modernes, les couleurs rouge et verte servaient déjà à organiser la circulation ferroviaire. Ce code a ensuite été repris pour guider les automobilistes.', 'Smithsonian Magazine', 'https://www.smithsonianmag.com/innovation/history-of-the-traffic-light-180982902/', 'quotidien-societe', 167, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('les-restaurants-modernes-doivent-beaucoup-a-paris', 'Les restaurants modernes doivent beaucoup à Paris.', 'Le restaurant devient un lieu où l’on choisit son repas.', 'À la fin du XVIIIe siècle, Paris voit se développer des établissements où l’on commande à la carte. L’idée paraît normale aujourd’hui, mais elle a changé notre rapport au repas hors de chez soi.', 'Encyclopaedia Britannica', 'https://www.britannica.com/topic/restaurant', 'quotidien-societe', 168, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('la-publicite-vend-souvent-une-emotion-avant-un-produit', 'La publicité vend souvent une émotion avant un produit.', 'On achète parfois une image autant qu’un objet.', 'Une marque ne montre pas seulement ce qu’elle vend : elle associe le produit à une envie, un statut ou une sensation. C’est pour cela que certaines pubs racontent presque une mini-histoire.', 'NielsenIQ', 'https://nielseniq.com/global/en/insights/', 'quotidien-societe', 169, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('les-cartes-bancaires-ont-rendu-largent-moins-visible', 'Les cartes bancaires ont rendu l’argent moins visible.', 'Payer sans billets change notre rapport à la dépense.', 'Quand l’argent devient une carte ou un geste sans contact, la transaction paraît plus abstraite. Cette simplicité a transformé nos habitudes d’achat.', 'Banque de France', 'https://www.banque-france.fr/fr/stabilite-financiere/moyens-paiement-scripturaux', 'quotidien-societe', 170, '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('le-mot-spam-vient-aussi-dun-sketch-des-monty-python', 'Le mot “spam” vient aussi d’un sketch des Monty Python.', 'Un mot d’Internet vient d’une blague répétitive.', 'Dans le sketch, le mot “Spam” revient sans cesse jusqu’à envahir la conversation. L’image a ensuite servi à désigner les messages indésirables qui saturent les boîtes mail.', 'Merriam-Webster', 'https://www.merriam-webster.com/dictionary/spam', 'mots-origines', 171, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-quiz-a-une-origine-incertaine', 'Le mot “quiz” a une origine incertaine.', 'Même les mots courants peuvent garder un mystère.', 'On raconte souvent des histoires amusantes sur son invention, mais son origine exacte reste discutée. C’est un bon exemple de mot très utilisé dont le passé est moins clair qu’on l’imagine.', 'Oxford English Dictionary', 'https://www.oed.com/', 'mots-origines', 172, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-avatar-vient-du-sanskrit', 'Le mot “avatar” vient du sanskrit.', 'Un mot numérique existait bien avant Internet.', 'À l’origine, il désigne la descente d’une divinité sur terre dans la tradition hindoue. Aujourd’hui, il sert à parler de notre représentation dans un monde virtuel.', 'Encyclopaedia Britannica', 'https://www.britannica.com/topic/avatar-Hinduism', 'mots-origines', 173, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-slogan-vient-dun-cri-de-guerre', 'Le mot “slogan” vient d’un cri de guerre.', 'Une phrase publicitaire garde une origine guerrière.', 'Le mot vient d’une expression gaélique liée au cri d’un clan. Avec le temps, il a fini par désigner une formule courte utilisée pour marquer les esprits.', 'Merriam-Webster', 'https://www.merriam-webster.com/dictionary/slogan', 'mots-origines', 174, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-clue-voulait-dire-pelote-de-fil', 'Le mot “clue” voulait dire pelote de fil.', 'Un indice garde la trace du mythe du labyrinthe.', 'En anglais, “clue” vient d’un mot lié à une boule de fil. L’image rappelle le fil permettant de retrouver son chemin, comme dans l’histoire du labyrinthe.', 'Online Etymology Dictionary', 'https://www.etymonline.com/word/clue', 'mots-origines', 175, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-panique-vient-du-dieu-pan', 'Le mot “panique” vient du dieu Pan.', 'Une peur collective porte le nom d’un dieu grec.', 'Dans la mythologie, Pan pouvait provoquer une peur soudaine et irrationnelle. Le mot a fini par désigner cette sensation de peur brutale qui se propage.', 'CNRTL', 'https://www.cnrtl.fr/definition/panique', 'mots-origines', 176, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-mentor-vient-de-lodyssee', 'Le mot “mentor” vient de l’Odyssée.', 'Un personnage antique devient le nom du guide idéal.', 'Dans le récit, Mentor est associé à l’accompagnement de Télémaque. Aujourd’hui, le mot désigne quelqu’un qui conseille et aide à progresser.', 'Merriam-Webster', 'https://www.merriam-webster.com/dictionary/mentor', 'mots-origines', 177, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-candidat-est-lie-a-la-couleur-blanche', 'Le mot “candidat” est lié à la couleur blanche.', 'Faire campagne avait aussi un code vestimentaire.', 'Dans la Rome antique, ceux qui briguaient une fonction portaient une toge blanchie pour se distinguer. Le mot a gardé cette trace dans son origine.', 'Online Etymology Dictionary', 'https://www.etymonline.com/word/candidate', 'mots-origines', 178, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-capuccino-vient-de-la-couleur-dun-habit-religieux', 'Le mot “capuccino” vient de la couleur d’un habit religieux.', 'Une boisson porte le nom d’une robe de moine.', 'Le cappuccino rappelle la couleur de l’habit des moines capucins. C’est un exemple simple de mot né d’une comparaison visuelle.', 'Merriam-Webster', 'https://www.merriam-webster.com/dictionary/cappuccino', 'mots-origines', 179, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('le-mot-nostalgie-a-dabord-ete-un-terme-medical', 'Le mot “nostalgie” a d’abord été un terme médical.', 'Le mal du pays était autrefois vu comme une maladie.', 'Au départ, la nostalgie désignait la souffrance ressentie loin de chez soi. Le mot a ensuite pris un sens plus large, lié au regret du passé.', 'CNRTL', 'https://www.cnrtl.fr/definition/nostalgie', 'mots-origines', 180, '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('la-russie-setend-sur-onze-fuseaux-horaires', 'La Russie s’étend sur onze fuseaux horaires.', 'Un seul pays couvre une immense largeur du globe.', 'Son territoire va de l’Europe de l’Est jusqu’au Pacifique. Cette taille explique pourquoi parler de “la Russie” revient à évoquer des réalités géographiques très différentes.', 'Encyclopaedia Britannica', 'https://www.britannica.com/place/Russia', 'geographie-monde', 181, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('le-detroit-de-gibraltar-separe-leurope-de-lafrique', 'Le détroit de Gibraltar sépare l’Europe de l’Afrique.', 'À cet endroit, deux continents se font presque face.', 'Entre l’Espagne et le Maroc, la Méditerranée communique avec l’océan Atlantique. Ce passage étroit a toujours eu une importance stratégique immense.', 'Encyclopaedia Britannica', 'https://www.britannica.com/place/Strait-of-Gibraltar', 'geographie-monde', 182, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('madagascar-possede-une-biodiversite-tres-particuliere', 'Madagascar possède une biodiversité très particulière.', 'L’isolement a créé une nature presque unique.', 'Comme l’île est séparée du continent africain depuis très longtemps, beaucoup d’espèces y ont évolué à part. C’est pourquoi on y trouve des animaux et plantes qu’on ne voit presque nulle part ailleurs.', 'World Wildlife Fund', 'https://www.worldwildlife.org/places/madagascar', 'geographie-monde', 183, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('le-danube-traverse-ou-borde-de-nombreux-pays-europeens', 'Le Danube traverse ou borde de nombreux pays européens.', 'Un fleuve peut relier plus qu’il ne sépare.', 'Il part d’Europe centrale et traverse plusieurs capitales ou régions importantes. Son parcours en fait l’un des grands axes historiques et culturels du continent.', 'Encyclopaedia Britannica', 'https://www.britannica.com/place/Danube-River', 'geographie-monde', 184, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('la-mediterranee-a-longtemps-ete-une-autoroute-du-commerce', 'La Méditerranée a longtemps été une autoroute du commerce.', 'La mer reliait les civilisations avant de les séparer.', 'Phéniciens, Grecs, Romains et marchands médiévaux l’ont utilisée pour échanger des produits, des idées et des techniques. Son histoire explique une grande partie de la culture européenne.', 'Encyclopaedia Britannica', 'https://www.britannica.com/place/Mediterranean-Sea', 'geographie-monde', 185, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('lamazonie-produit-une-grande-partie-de-sa-propre-pluie', 'L’Amazonie produit une grande partie de sa propre pluie.', 'La forêt aide à fabriquer son climat.', 'Les arbres rejettent beaucoup d’humidité dans l’air, ce qui participe au cycle des pluies. La forêt n’est donc pas seulement victime du climat : elle contribue aussi à le maintenir.', 'NASA Earth Observatory', 'https://earthobservatory.nasa.gov/features/AmazonRainforest', 'geographie-monde', 186, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('la-coree-est-divisee-en-deux-etats-depuis-le-xxe-siecle', 'La Corée est divisée en deux États depuis le XXe siècle.', 'Une frontière résume encore la guerre froide en Asie.', 'Après la Seconde Guerre mondiale puis la guerre de Corée, le Nord et le Sud restent séparés. Cette division reste l’un des grands héritages géopolitiques du XXe siècle.', 'Encyclopaedia Britannica', 'https://www.britannica.com/place/Korea', 'geographie-monde', 187, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('le-canal-de-panama-relie-deux-oceans', 'Le canal de Panama relie deux océans.', 'Un passage artificiel évite de contourner l’Amérique du Sud.', 'Ouvert en 1914, il permet aux navires de passer entre Atlantique et Pacifique beaucoup plus rapidement. C’est l’un des ouvrages les plus stratégiques du commerce maritime.', 'Panama Canal Authority', 'https://pancanal.com/en/history-of-the-panama-canal/', 'geographie-monde', 188, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('la-nouvelle-zelande-est-lun-des-derniers-grands-territoires-peuples-par-lhumain', 'La Nouvelle-Zélande est l’un des derniers grands territoires peuplés par l’humain.', 'Certaines îles ont été habitées très tard dans l’histoire humaine.', 'Les Polynésiens arrivent en Nouvelle-Zélande plusieurs siècles seulement avant les Européens. Cela rappelle que la présence humaine sur certaines terres est beaucoup plus récente qu’on l’imagine.', 'Te Ara Encyclopedia of New Zealand', 'https://teara.govt.nz/en/history', 'geographie-monde', 189, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('le-groenland-est-immense-mais-tres-peu-peuple', 'Le Groenland est immense mais très peu peuplé.', 'Une grande taille ne signifie pas une grande population.', 'La majeure partie du territoire est couverte par une calotte glaciaire, ce qui rend l’installation humaine difficile. C’est pourquoi sa population reste concentrée surtout sur les côtes.', 'Encyclopaedia Britannica', 'https://www.britannica.com/place/Greenland', 'geographie-monde', 190, '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
  ('le-blues-est-lune-des-racines-du-rock', 'Le blues est l’une des racines du rock.', 'Le rock vient en partie d’une musique née de la douleur.', 'Le blues naît dans l’expérience afro-américaine et influence ensuite le jazz, le rhythm and blues et le rock. Beaucoup de musiques modernes lui doivent une partie de leur langage.', 'Smithsonian Music', 'https://music.si.edu/story/roots-blues', 'musique-culture', 191, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('le-rap-met-le-texte-au-premier-plan', 'Le rap met le texte au premier plan.', 'Dans le rap, la parole devient instrument principal.', 'Le rythme compte, mais les rimes, le flow et le récit donnent au rap sa force particulière. C’est l’une des raisons pour lesquelles il peut porter à la fois fête, colère et témoignage social.', 'Smithsonian Music', 'https://music.si.edu/spotlight/hip-hop', 'musique-culture', 192, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('la-musique-classique-couvre-plusieurs-siecles-tres-differents', 'La musique classique couvre plusieurs siècles très différents.', '“Classique” ne veut pas dire une seule époque.', 'Bach, Mozart, Beethoven ou Debussy n’appartiennent pas au même moment ni au même style. Le mot sert souvent de raccourci pour des traditions musicales très variées.', 'Encyclopaedia Britannica', 'https://www.britannica.com/art/Western-music', 'musique-culture', 193, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('queen-doit-beaucoup-a-la-voix-de-freddie-mercury', 'Queen doit beaucoup à la voix de Freddie Mercury.', 'Une voix peut devenir l’identité d’un groupe.', 'Freddie Mercury mêlait puissance, théâtralité et sens du spectacle. C’est ce qui a aidé Queen à devenir reconnaissable dès les premières secondes de certaines chansons.', 'Rock & Roll Hall of Fame', 'https://rockhall.com/inductees/queen/', 'musique-culture', 194, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('le-reggae-est-lie-a-lhistoire-sociale-de-la-jamaique', 'Le reggae est lié à l’histoire sociale de la Jamaïque.', 'Une musique peut porter une identité collective.', 'Le reggae ne se résume pas à un rythme détendu : il parle aussi de spiritualité, de résistance et de vie sociale. Bob Marley l’a rendu mondialement visible.', 'Encyclopaedia Britannica', 'https://www.britannica.com/art/reggae', 'musique-culture', 195, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('la-disco-a-transforme-les-pistes-de-danse-des-annees-1970', 'La disco a transformé les pistes de danse des années 1970.', 'La musique devient aussi une culture de club.', 'Avec ses rythmes réguliers et ses productions brillantes, la disco accompagne l’essor des discothèques. Elle marque la mode, la danse et l’idée de fête moderne.', 'Encyclopaedia Britannica', 'https://www.britannica.com/art/disco', 'musique-culture', 196, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('le-punk-nait-comme-une-reaction-brute-au-rock-installe', 'Le punk naît comme une réaction brute au rock installé.', 'Quelques accords suffisent à créer une rupture culturelle.', 'Dans les années 1970, le punk valorise l’énergie, la provocation et le “fais-le toi-même”. Il influence autant la musique que la mode et l’attitude.', 'Rock & Roll Hall of Fame', 'https://rockhall.com/', 'musique-culture', 197, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('madonna-a-fait-de-limage-une-partie-centrale-de-la-pop', 'Madonna a fait de l’image une partie centrale de la pop.', 'La pop devient autant visuelle que musicale.', 'Avec ses clips, ses looks et ses changements d’identité, Madonna montre qu’une star pop peut se réinventer en permanence. Son influence dépasse largement ses chansons.', 'Rock & Roll Hall of Fame', 'https://rockhall.com/inductees/madonna/', 'musique-culture', 198, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('le-flamenco-mele-chant-danse-et-guitare', 'Le flamenco mêle chant, danse et guitare.', 'Un art andalou transforme l’émotion en rythme.', 'Né dans le sud de l’Espagne, il combine la voix, le mouvement et la percussion du corps. C’est une culture expressive, pas seulement un style musical.', 'UNESCO', 'https://ich.unesco.org/en/RL/flamenco-00363', 'musique-culture', 199, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]'),
  ('la-fete-de-la-musique-est-nee-en-france-en-1982', 'La Fête de la musique est née en France en 1982.', 'Une idée simple transforme la ville en scène ouverte.', 'Le principe est d’encourager les musiciens amateurs et professionnels à jouer dans l’espace public. L’événement s’est ensuite diffusé dans de nombreux pays.', 'Ministère de la Culture', 'https://www.culture.gouv.fr/Thematiques/Musique/Fete-de-la-musique', 'musique-culture', 200, '#ef4444', 'from-[#220b0b] via-[#991b1b] to-[#fca5a5]')
)
INSERT INTO public.facts (slug, title, hook, content, source, source_url, category_id, display_order, accent_color, tone, status, published_at)
SELECT
  nf.slug, nf.title, nf.hook, nf.content, nf.source, nf.source_url, c.id, nf.display_order, nf.accent_color, nf.tone, 'published', now()
FROM new_facts nf
JOIN public.categories c ON c.slug = nf.category_slug
WHERE NOT EXISTS (
  SELECT 1 FROM public.facts existing WHERE existing.slug = nf.slug
);

COMMIT;
